import { useState, useMemo, useEffect, useRef, type ReactNode } from 'react';
import { useSuspenseQuery, useQueryClient } from '@tanstack/react-query';
import { useServerFn } from '@tanstack/react-start';
import { toast } from 'sonner';
import { Plus, Trash2, Save, Youtube, Download, ExternalLink, X, CalendarDays, Link2, ShieldCheck, Send } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { hubOptions, saveHub, importYouTube, lookupYouTube, checkYouTubeHealth, type YouTubeLookup, getPlannerComments, PLANNER_STAGES, STAGE_LABELS, SOURCE_TYPES, SOURCE_TYPE_LABELS, type VideoRow, type PostRow, type DataCardRow, type SourceRow, type PlannerRow, type ContentSourceRow } from '@/lib/hub.functions';
import { publicNewsOptions, newsroomOptions, type Category } from '@/lib/news.functions';
import { isOlderData } from '@/lib/news';
import { parseYouTubeLink, watchUrl, formatDuration, needsDetails } from '@/lib/youtube';
import { YouTubeThumb } from '../news/youtube';
import { StoryEditor } from './editor';
import { uploadPhoto } from './media';
import { categoryName } from '../news/public-site';

type Media = { path: string; url?: string | undefined; alt: string; credit?: string | undefined };
type Team = { id: string; name: string }[];
export type HubKind = 'videos' | 'posts' | 'data' | 'sources' | 'planner' | 'activity';
type SourceLink = { source_id: string | null; title: string; url: string; source_type: (typeof SOURCE_TYPES)[number]; data_year: string; accessed_at: string | null; page_ref: string; note: string };
const F = ({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) => <div className="mt-4"><label className="field-label">{label}</label>{children}{hint && <p className="text-xs text-muted-foreground mt-1">{hint}</p>}</div>;
const toLocal = (iso?: string | null) => (iso ? new Date(new Date(iso).getTime() - new Date(iso).getTimezoneOffset() * 60000).toISOString().slice(0, 16) : '');
const fromLocal = (v: string) => (v ? new Date(v).toISOString() : null);
const slug = (s: string) => s.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 70);
const badge = (s: string) => <span className={`text-[10px] font-bold uppercase rounded px-2 py-1 ${s === 'published' ? 'bg-primary/15 text-primary' : s === 'scheduled' ? 'bg-accent/20' : 'bg-muted'}`}>{s}</span>;

function useSaver() {
  const qc = useQueryClient(); const save = useServerFn(saveHub); const [busy, setBusy] = useState(false);
  async function run(payload: unknown, msg = 'Saved'): Promise<{ id: string } | null> {
    setBusy(true);
    try { const r = (await save({ data: payload as never })) as { id: string }; await qc.invalidateQueries({ queryKey: hubOptions.queryKey }); await qc.invalidateQueries({ queryKey: publicNewsOptions.queryKey }); toast.success(msg); return r; }
    catch (e) { toast.error(e instanceof Error ? e.message : 'Could not save'); return null; } finally { setBusy(false); }
  }
  return { run, busy };
}

/** Editable list of proofs shown to the public under a video or blog post. */
function SourcesEditor({ items, onChange, library }: { items: SourceLink[]; onChange: (v: SourceLink[]) => void; library: SourceRow[] }) {
  const set = (i: number, p: Partial<SourceLink>) => onChange(items.map((x, k) => (k === i ? { ...x, ...p } : x)));
  const addFrom = (id: string) => { const s = library.find((x) => x.id === id); if (!s) return; onChange([...items, { source_id: s.id, title: s.name, url: /^https?:\/\//i.test(s.website) ? s.website : `https://${s.website.split(/[\s/]+/)[0]}`, source_type: s.source_type as SourceLink['source_type'], data_year: '', accessed_at: new Date().toISOString().slice(0, 10), page_ref: '', note: '' }]); };
  return <div className="admin-panel mt-6"><h3 className="font-bold flex gap-2 items-center"><Link2 size={16} />Sources &amp; Proofs <span className="text-xs font-normal text-muted-foreground">(shown to viewers)</span></h3>
    {items.map((x, i) => <div key={i} className="border border-border rounded-lg p-3 mt-3 grid gap-2 sm:grid-cols-2">
      <input className="field" placeholder="Document / page title" value={x.title} onChange={(e) => set(i, { title: e.target.value })} /><input className="field" placeholder="https://link-to-the-document" value={x.url} onChange={(e) => set(i, { url: e.target.value })} />
      <select className="field" value={x.source_type} onChange={(e) => set(i, { source_type: e.target.value as SourceLink['source_type'] })}>{SOURCE_TYPES.map((t) => <option key={t} value={t}>{SOURCE_TYPE_LABELS[t]}</option>)}</select>
      <input className="field" placeholder="Data / document year" value={x.data_year} onChange={(e) => set(i, { data_year: e.target.value })} /><input className="field" type="date" aria-label="Date accessed" value={x.accessed_at || ''} onChange={(e) => set(i, { accessed_at: e.target.value || null })} /><input className="field" placeholder="Page / section" value={x.page_ref} onChange={(e) => set(i, { page_ref: e.target.value })} />
      <input className="field sm:col-span-2" placeholder="Note (optional)" value={x.note} onChange={(e) => set(i, { note: e.target.value })} /><div className="sm:col-span-2 text-right"><Button type="button" variant="ghost" size="sm" onClick={() => onChange(items.filter((_, k) => k !== i))}><Trash2 />Remove</Button></div></div>)}
    <div className="flex flex-wrap gap-3 mt-4"><Button type="button" variant="outline" size="sm" onClick={() => onChange([...items, { source_id: null, title: '', url: '', source_type: 'government', data_year: '', accessed_at: new Date().toISOString().slice(0, 10), page_ref: '', note: '' }])}><Plus />Add a link</Button>
      <select className="field !w-auto" value="" onChange={(e) => { addFrom(e.target.value); e.currentTarget.value = ''; }} aria-label="Add from Source Library"><option value="">+ Add from Source Library…</option>{library.map((s) => <option key={s.id} value={s.id}>{s.ref} · {s.name.slice(0, 70)}</option>)}</select></div></div>;
}
const rowsToLinks = (rows: ContentSourceRow[]): SourceLink[] => rows.map((s) => ({ source_id: s.source_id, title: s.title, url: s.url, source_type: s.source_type as SourceLink['source_type'], data_year: s.data_year, accessed_at: s.accessed_at, page_ref: s.page_ref, note: s.note }));
const CatSelect = ({ value, onChange, categories }: { value: string | null; onChange: (v: string | null) => void; categories: Category[] }) => <select className="field" value={value || ''} onChange={(e) => onChange(e.target.value || null)}><option value="">— choose a category —</option>{categories.map((c) => <option key={c.id} value={c.id}>{categoryName(c, 'en')}</option>)}</select>;
const StatusSelect = ({ value, onChange, canPublish, scheduled = true }: { value: string; onChange: (v: string) => void; canPublish: boolean; scheduled?: boolean }) => <select className="field" value={value} onChange={(e) => onChange(e.target.value)}><option value="draft">Draft</option><option value="review">Ready for review</option>{canPublish && <>{scheduled && <option value="scheduled">Scheduled</option>}<option value="published">Published</option><option value="unpublished">Unpublished</option><option value="archived">Archived</option></>}</select>;

/* ------------------------------ Videos ------------------------------ */
type VideoFormState = { youtube: string; slug: string; title_te: string; title_en: string; description_te: string; description_en: string; category_id: string | null; language: 'te' | 'en'; series: string; region: string; tags: string; status: string; publish_at: string; is_featured: boolean; show_in_ticker: boolean; instagram: string; facebook: string; seo_title: string; seo_description: string; is_short: boolean; duration_seconds: number | null; yt_published_at: string | null; yt_channel: string };
function videoState(row?: VideoRow): VideoFormState {
  const sl = (row?.social_links && typeof row.social_links === 'object' ? row.social_links : {}) as Record<string, string>;
  return { youtube: row?.youtube_id ? watchUrl(row.youtube_id, row.is_short) : '', slug: row?.slug || '', title_te: row?.title_te || '', title_en: row?.title_en || '', description_te: row?.description_te || '', description_en: row?.description_en || '', category_id: row?.category_id || null, language: (row?.language || 'te') as 'te' | 'en', series: row?.series || '', region: row?.region || '', tags: (row?.tags || []).join(', '), status: row?.status || 'draft', publish_at: toLocal(row?.publish_at), is_featured: row?.is_featured || false, show_in_ticker: row?.show_in_ticker ?? true, instagram: sl['instagram'] || '', facebook: sl['facebook'] || '', seo_title: row?.seo_title || '', seo_description: row?.seo_description || '', is_short: row?.is_short || false, duration_seconds: row?.duration_seconds ?? null, yt_published_at: row?.yt_published_at || null, yt_channel: row?.yt_channel || '' };
}
function videoPayload(f: VideoFormState, id: string | undefined, sources: SourceLink[], status = f.status) {
  return { kind: 'video', value: { ...(id ? { id } : {}), slug: f.slug || slug(f.title_en), title_te: f.title_te, title_en: f.title_en, description_te: f.description_te, description_en: f.description_en, youtube: f.youtube, is_short: f.is_short, duration_seconds: f.duration_seconds, yt_published_at: f.yt_published_at, yt_channel: f.yt_channel, category_id: f.category_id, tags: f.tags.split(',').map((t) => t.trim()).filter(Boolean), region: f.region, language: f.language, series: f.series, status: status as 'draft', publish_at: fromLocal(f.publish_at), is_featured: f.is_featured, show_in_ticker: f.show_in_ticker, social_links: { youtube: '', instagram: f.instagram, facebook: f.facebook }, seo_title: f.seo_title, seo_description: f.seo_description, sources } };
}
const AVAIL_TEXT: Record<string, string> = { not_embeddable: 'The channel owner has switched off embedding for this video. Visitors will see a “Watch on YouTube” button instead of the player.', unavailable: 'YouTube says this video is private or removed. Check the link before publishing.', unknown: 'YouTube could not be reached just now, so the title was not filled in. You can type it, or try again later.' };

function VideoForm({ row, onDone, categories, canPublish, openExisting }: { row?: VideoRow; onDone: () => void; categories: Category[]; canPublish: boolean; openExisting: (id: string) => void }) {
  const { data } = useSuspenseQuery(hubOptions); const { run, busy } = useSaver(); const lookup = useServerFn(lookupYouTube);
  const [f, setF] = useState<VideoFormState>(() => videoState(row));
  const [sources, setSources] = useState<SourceLink[]>(row ? rowsToLinks(data.contentSources.filter((c) => c.content_type === 'video' && c.content_id === row.id)) : []);
  const [info, setInfo] = useState<{ state: 'idle' | 'checking' | 'done' | 'error'; message?: string; lookup?: YouTubeLookup }>({ state: 'idle' });
  const set = (p: Partial<VideoFormState>) => setF((x) => ({ ...x, ...p }));
  const link = parseYouTubeLink(f.youtube); const lastChecked = useRef('');
  async function check(value: string) {
    const parsed = parseYouTubeLink(value);
    if (!value.trim()) { setInfo({ state: 'idle' }); return; }
    if (!parsed) { setInfo({ state: 'error', message: 'This is not a YouTube video link. In the YouTube app tap Share → Copy link, then paste it here.' }); return; }
    if (lastChecked.current === parsed.id) return; lastChecked.current = parsed.id;
    setInfo({ state: 'checking' });
    try {
      const r = await lookup({ data: { link: value, exceptId: row?.id ?? null } });
      setInfo({ state: 'done', lookup: r });
      if (r.duplicate) return;
      setF((x) => ({ ...x, is_short: x.is_short || r.isShort, duration_seconds: r.seconds ?? x.duration_seconds, yt_published_at: r.publishedAt || x.yt_published_at, yt_channel: r.channel || x.yt_channel,
        ...(r.title && r.titleField === 'te' && !x.title_te.trim() ? { title_te: r.title, language: 'te' as const } : {}), ...(r.title && r.titleField === 'en' && !x.title_en.trim() ? { title_en: r.title } : {}),
        ...(r.description && r.titleField === 'te' && !x.description_te.trim() ? { description_te: r.description } : {}), ...(r.description && r.titleField === 'en' && !x.description_en.trim() ? { description_en: r.description } : {}),
        ...(r.tags.length && !x.tags.trim() ? { tags: r.tags.slice(0, 15).join(', ') } : {}) }));
    } catch (e) { lastChecked.current = ''; setInfo({ state: 'error', message: e instanceof Error ? e.message : 'The link could not be checked.' }); }
  }
  const dup = info.lookup?.duplicate;
  const missing = needsDetails({ category_id: f.category_id, title_te: f.title_te, title_en: f.title_en, youtube_id: link?.id || '' }, sources.length);
  async function submit() { if (dup) { toast.error('This video is already on the website.'); return; } const r = await run(videoPayload(f, row?.id, sources), 'Video saved'); if (r) onDone(); }
  return <div className="admin-panel mb-8"><div className="flex justify-between"><h2 className="font-bold text-xl">{row ? 'Edit video' : 'Add video'}</h2><Button variant="ghost" size="icon" aria-label="Close" onClick={onDone}><X /></Button></div>
    <p className="text-sm text-muted-foreground mt-1">Post the video on YouTube first, then paste its link here. Nothing is uploaded to the website — the thumbnail and player come from YouTube.</p>
    <F label="YouTube link (required)" hint="Works with normal, youtu.be, Shorts and live links. The title fills in automatically.">
      <input className="field" value={f.youtube} placeholder="https://www.youtube.com/watch?v=…  or  https://youtube.com/shorts/…" aria-label="YouTube link"
        onChange={(e) => { set({ youtube: e.target.value }); if (!e.target.value.trim()) setInfo({ state: 'idle' }); }} onBlur={(e) => void check(e.target.value)} onPaste={(e) => { const v = e.clipboardData.getData('text'); setTimeout(() => void check(v), 0); }} />
    </F>
    <div className="mt-3 flex flex-wrap gap-4 items-start" aria-live="polite">
      {link && <div className={`overflow-hidden rounded-lg border border-border bg-muted ${f.is_short ? 'w-36 aspect-[9/16]' : 'w-64 aspect-video'}`}><YouTubeThumb id={link.id} isShort={f.is_short} alt="YouTube thumbnail preview" eager className="h-full w-full" /></div>}
      <div className="text-sm space-y-1 min-w-0 flex-1">
        {info.state === 'checking' && <p className="text-muted-foreground">Checking the link with YouTube…</p>}
        {info.state === 'error' && <p className="text-destructive font-medium">{info.message}</p>}
        {dup && <div className="rounded-lg border border-destructive/40 bg-destructive/10 p-3"><p className="font-semibold text-destructive">This video is already on the website.</p><p className="text-xs mt-1">“{dup.title}” · {dup.status}</p><Button type="button" size="sm" variant="outline" className="mt-2" onClick={() => openExisting(dup.id)}>Open the existing entry</Button></div>}
        {info.state === 'done' && !dup && info.lookup && <>
          <p><strong>{info.lookup.title || 'Title not available'}</strong>{info.lookup.channel ? <span className="text-muted-foreground"> · {info.lookup.channel}</span> : null}</p>
          <p className="text-xs text-muted-foreground">ID {info.lookup.id}{f.is_short ? ' · Short' : ''}{f.duration_seconds ? ` · ${formatDuration(f.duration_seconds)}` : ''}</p>
          {AVAIL_TEXT[info.lookup.availability] && <p className="text-xs text-accent-foreground bg-accent/20 rounded p-2">{AVAIL_TEXT[info.lookup.availability]}</p>}
          {info.lookup.maybeShort && !f.is_short && <p className="text-xs text-muted-foreground">This video is 3 minutes or shorter. If it was posted as a YouTube Short, tick “This is a YouTube Short” below.</p>}
          {!info.lookup.usedApi && <p className="text-xs text-muted-foreground">Description, length and publish date are filled in automatically only when the YOUTUBE_API_KEY server secret is set — otherwise type them below.</p>}
        </>}
        {link && <a className="text-xs text-primary inline-flex gap-1 items-center" href={watchUrl(link.id, f.is_short)} target="_blank" rel="noopener noreferrer"><ExternalLink size={12} />Open on YouTube</a>}
      </div>
    </div>
    <label className="flex gap-2 items-center mt-4 text-sm"><input type="checkbox" checked={f.is_short} onChange={(e) => set({ is_short: e.target.checked })} />This is a YouTube Short (vertical video)</label>
    <div className="grid sm:grid-cols-2 gap-x-4"><F label="Title (Telugu)"><input className="field" value={f.title_te} onChange={(e) => set({ title_te: e.target.value })} /></F><F label="Title (English)"><input className="field" value={f.title_en} onChange={(e) => set({ title_en: e.target.value })} /></F>
      <F label="Description (Telugu)"><textarea className="field min-h-28" value={f.description_te} onChange={(e) => set({ description_te: e.target.value })} /></F><F label="Description (English)"><textarea className="field min-h-28" value={f.description_en} onChange={(e) => set({ description_en: e.target.value })} /></F>
      <F label="Category (required to publish)"><CatSelect value={f.category_id} onChange={(v) => set({ category_id: v })} categories={categories} /></F><F label="Video language"><select className="field" value={f.language} onChange={(e) => set({ language: e.target.value as 'te' | 'en' })}><option value="te">Telugu</option><option value="en">English</option></select></F>
      <F label="Series (optional)"><input className="field" value={f.series} onChange={(e) => set({ series: e.target.value })} placeholder="e.g. Reality Check" /></F><F label="Region"><input className="field" value={f.region} onChange={(e) => set({ region: e.target.value })} placeholder="e.g. Visakhapatnam" /></F>
      <F label="Tags (commas)"><input className="field" value={f.tags} onChange={(e) => set({ tags: e.target.value })} /></F><F label="Web address"><input className="field" value={f.slug} onChange={(e) => set({ slug: slug(e.target.value) })} placeholder="auto from the English title" /></F>
      <F label="Instagram reel link (optional)"><input className="field" value={f.instagram} onChange={(e) => set({ instagram: e.target.value })} /></F><F label="Facebook post link (optional)"><input className="field" value={f.facebook} onChange={(e) => set({ facebook: e.target.value })} /></F>
      <F label="Status"><StatusSelect value={f.status} onChange={(v) => set({ status: v })} canPublish={canPublish} /></F>{f.status === 'scheduled' && <F label="Publish time"><input type="datetime-local" className="field" value={f.publish_at} onChange={(e) => set({ publish_at: e.target.value })} /></F>}</div>
    <label className="flex gap-2 items-center mt-4 text-sm"><input type="checkbox" checked={f.show_in_ticker} onChange={(e) => set({ show_in_ticker: e.target.checked })} />Show in the top ticker (automatic when published)</label><label className="flex gap-2 items-center mt-2 text-sm"><input type="checkbox" checked={f.is_featured} onChange={(e) => set({ is_featured: e.target.checked })} />Featured video</label>
    <details className="mt-4"><summary className="cursor-pointer text-sm font-semibold">Search appearance (optional)</summary><F label="Search title"><input className="field" value={f.seo_title} onChange={(e) => set({ seo_title: e.target.value })} /></F><F label="Search description"><textarea className="field" value={f.seo_description} onChange={(e) => set({ seo_description: e.target.value })} /></F></details>
    <SourcesEditor items={sources} onChange={setSources} library={data.sources} />
    {missing.length > 0 && <p className="mt-4 text-sm rounded bg-accent/20 p-2"><strong>Needs details:</strong> {missing.join(', ')}.</p>}
    <div className="mt-6 flex gap-3"><Button disabled={busy || !!dup || info.state === 'checking'} onClick={submit}><Save />Save video</Button><Button variant="outline" onClick={onDone}>Cancel</Button></div></div>;
}
function VideosAdmin({ categories, canPublish }: { categories: Category[]; canPublish: boolean }) {
  const { data } = useSuspenseQuery(hubOptions); const qc = useQueryClient(); const [edit, setEdit] = useState<VideoRow | 'new' | null>(null); const { run } = useSaver(); const imp = useServerFn(importYouTube); const health = useServerFn(checkYouTubeHealth); const [busy, setBusy] = useState(false);
  const srcCount = (id: string) => data.contentSources.filter((c) => c.content_type === 'video' && c.content_id === id).length;
  async function doImport() { setBusy(true); try { const r = await imp(); toast.success(`${r.added} new video(s) added as drafts (${r.found} found in the channel feed).`); await qc.invalidateQueries({ queryKey: hubOptions.queryKey }); } catch (e) { toast.error(e instanceof Error ? e.message : 'Import failed'); } finally { setBusy(false); } }
  async function doHealth() { setBusy(true); try { const r = await health(); toast.success(`Checked ${r.checked} live video(s): ${r.ok} fine, ${r.problems} need attention${r.unknown ? `, ${r.unknown} could not be checked (YouTube not reachable)` : ''}.`); await qc.invalidateQueries({ queryKey: hubOptions.queryKey }); } catch (e) { toast.error(e instanceof Error ? e.message : 'Check failed'); } finally { setBusy(false); } }
  async function publishNow(v: VideoRow) { await run(videoPayload(videoState(v), v.id, rowsToLinks(data.contentSources.filter((c) => c.content_type === 'video' && c.content_id === v.id)), 'published'), 'Video published'); }
  const openExisting = (id: string) => { const r = data.videos.find((x) => x.id === id); if (r) setEdit(r); };
  return <><div className="flex flex-wrap justify-between gap-3 mb-6"><h1 className="text-3xl font-bold">Videos</h1><div className="flex flex-wrap gap-3">{canPublish && <><Button variant="outline" disabled={busy} onClick={doHealth}><ShieldCheck />Check YouTube links</Button><Button variant="outline" disabled={busy} onClick={doImport}><Download />Import from YouTube</Button></>}<Button onClick={() => setEdit('new')}><Plus />Add video</Button></div></div>
    {edit && <VideoForm key={edit === 'new' ? 'new' : edit.id} {...(edit === 'new' ? {} : { row: edit })} onDone={() => setEdit(null)} categories={categories} canPublish={canPublish} openExisting={openExisting} />}
    <div className="admin-panel overflow-x-auto">{data.videos.length ? <table className="w-full text-sm"><tbody>{data.videos.map((v) => { const miss = needsDetails(v, srcCount(v.id)); const live = ['published', 'scheduled'].includes(v.status);
      return <tr key={v.id} className="border-b border-border"><td className="py-3 pr-3 w-28"><div className={`overflow-hidden rounded bg-muted ${v.is_short ? 'w-14 aspect-[9/16] mx-auto' : 'w-24 aspect-video'}`}><YouTubeThumb id={v.youtube_id} isShort={v.is_short} alt="" className="h-full w-full" /></div></td>
        <td className="py-3"><p className="font-semibold">{v.title_te || v.title_en || '(untitled)'}</p><p className="text-xs text-muted-foreground">{categoryName(categories.find((c) => c.id === v.category_id), 'en') || 'No category'} · {v.language.toUpperCase()}{v.is_short ? ' · Short' : ''}{v.duration_seconds ? ` · ${formatDuration(v.duration_seconds)}` : ''}</p>
          <div className="flex flex-wrap gap-1.5 mt-1">{!live && miss.length > 0 && <span className="text-[10px] font-bold uppercase rounded px-2 py-0.5 bg-accent/30" title={`Missing: ${miss.join(', ')}`}>Needs details</span>}{(v.yt_status === 'unavailable' || v.yt_status === 'not_embeddable') && <span className="text-[10px] font-bold uppercase rounded px-2 py-0.5 bg-destructive/15 text-destructive" title={v.yt_checked_at ? `Checked ${new Date(v.yt_checked_at).toLocaleString()}` : ''}>{v.yt_status === 'unavailable' ? 'Video unavailable on YouTube' : 'Embedding switched off'}</span>}</div></td>
        <td>{badge(v.status)}</td><td className="text-right whitespace-nowrap">{canPublish && !live && miss.length === 0 && <Button size="sm" className="mr-2" onClick={() => void publishNow(v)}><Send />Publish</Button>}<Button size="sm" variant="outline" onClick={() => setEdit(v)}>Edit</Button>{canPublish && <Button size="icon" variant="ghost" aria-label="Delete" onClick={() => { if (window.confirm('Delete this video from the website? (It stays on YouTube.)')) void run({ kind: 'delete', value: { table: 'videos', id: v.id } }, 'Deleted'); }}><Trash2 /></Button>}</td></tr>; })}</tbody></table> : <p className="text-sm text-muted-foreground">No videos yet. Post on YouTube first, then click “Add video” and paste the link — or import from your YouTube channel.</p>}</div></>;
}

/* ------------------------------ Posts ------------------------------ */
function PostForm({ row, onDone, categories, canPublish, media, userId }: { row?: PostRow; onDone: () => void; categories: Category[]; canPublish: boolean; media: Media[]; userId: string }) {
  const { data } = useSuspenseQuery(hubOptions); const { run, busy } = useSaver(); const qc = useQueryClient(); const [lang, setLang] = useState<'te' | 'en'>('te');
  const [f, setF] = useState({ slug: row?.slug || '', post_type: (row?.post_type || 'blog') as PostRow['post_type'], title_te: row?.title_te || '', title_en: row?.title_en || '', body_te: row?.body_te || '<p></p>', body_en: row?.body_en || '<p></p>', cover_path: row?.cover_path || '', cover_alt: row?.cover_alt || '', cover_credit: row?.cover_credit || '', cover_youtube: row?.cover_youtube_id ? watchUrl(row.cover_youtube_id) : '', category_id: row?.category_id || null as string | null, tags: (row?.tags || []).join(', '), region: row?.region || '', status: row?.status || 'draft', publish_at: toLocal(row?.publish_at), seo_title: row?.seo_title || '', seo_description: row?.seo_description || '' });
  const [sources, setSources] = useState<SourceLink[]>(row ? rowsToLinks(data.contentSources.filter((c) => c.content_type === 'post' && c.content_id === row.id)) : []);
  const set = (p: Partial<typeof f>) => setF((x) => ({ ...x, ...p })); const cover = media.find((m) => m.path === f.cover_path);
  async function upload(file: File) { try { const m = await uploadPhoto(file, userId, f.cover_alt || file.name, f.cover_credit); await qc.invalidateQueries({ queryKey: newsroomOptions.queryKey }); set({ cover_path: m.path, cover_alt: f.cover_alt || m.alt }); toast.success('Photo uploaded'); } catch (e) { toast.error(e instanceof Error ? e.message : 'Upload failed'); } }
  async function submit() {
    const r = await run({ kind: 'post', value: { ...(row ? { id: row.id } : {}), slug: f.slug || slug(f.title_en), post_type: f.post_type, title_te: f.title_te, title_en: f.title_en, body_te: f.body_te, body_en: f.body_en, cover_path: f.cover_path, cover_alt: f.cover_alt, cover_credit: f.cover_credit, cover_youtube: f.cover_youtube, category_id: f.category_id, tags: f.tags.split(',').map((t) => t.trim()).filter(Boolean), region: f.region, status: f.status as 'draft', publish_at: fromLocal(f.publish_at), seo_title: f.seo_title, seo_description: f.seo_description, sources } }, 'Post saved');
    if (r) onDone();
  }
  return <div className="admin-panel mb-8"><div className="flex justify-between"><h2 className="font-bold text-xl">{row ? 'Edit post' : 'New post'}</h2><Button variant="ghost" size="icon" aria-label="Close" onClick={onDone}><X /></Button></div>
    <div className="grid sm:grid-cols-2 gap-x-4"><F label="Type"><select className="field" value={f.post_type} onChange={(e) => set({ post_type: e.target.value as typeof f.post_type })}><option value="blog">Blog article</option><option value="photo_story">Photo story</option><option value="data_story">Data story</option><option value="quick_update">Quick update</option></select></F><F label="Category"><CatSelect value={f.category_id} onChange={(v) => set({ category_id: v })} categories={categories} /></F>
      <F label="Title (Telugu)"><input className="field" value={f.title_te} onChange={(e) => set({ title_te: e.target.value })} /></F><F label="Title (English)"><input className="field" value={f.title_en} onChange={(e) => set({ title_en: e.target.value })} /></F></div>
    <div className="flex gap-2 mt-5">{(['te', 'en'] as const).map((l) => <Button key={l} type="button" size="sm" variant={lang === l ? 'default' : 'outline'} onClick={() => setLang(l)}>{l === 'te' ? 'Telugu text' : 'English text'}</Button>)}</div>
    <div className="mt-3">{lang === 'te' ? <StoryEditor key="te" value={f.body_te} onChange={(v) => set({ body_te: v })} /> : <StoryEditor key="en" value={f.body_en} onChange={(v) => set({ body_en: v })} />}</div>
    <F label="Cover photo (optional)"><div className="flex flex-wrap gap-3 items-center"><select className="field !w-auto" value={f.cover_path} onChange={(e) => { const m = media.find((x) => x.path === e.target.value); set({ cover_path: e.target.value, cover_alt: m?.alt || f.cover_alt, cover_credit: m?.credit || f.cover_credit }); }}><option value="">No cover</option>{media.map((m) => <option key={m.path} value={m.path}>{m.alt || m.path.split('/').pop()}</option>)}</select><input type="file" accept="image/jpeg,image/png,image/webp" aria-label="Upload cover photo" onChange={(e) => { const x = e.target.files?.[0]; if (x) void upload(x); }} />{cover?.url && <img src={cover.url} alt="" className="h-16 rounded" />}</div></F>
    {!f.cover_path && <F label="…or use a YouTube video's thumbnail as the cover (optional)" hint="Paste the YouTube link. Only the link is saved — no picture is copied to our storage."><div className="flex flex-wrap gap-3 items-center"><input className="field !w-auto flex-1 min-w-64" value={f.cover_youtube} onChange={(e) => set({ cover_youtube: e.target.value })} placeholder="https://www.youtube.com/watch?v=…" aria-label="YouTube cover link" />{parseYouTubeLink(f.cover_youtube) ? <div className="w-32 aspect-video overflow-hidden rounded bg-muted"><YouTubeThumb id={parseYouTubeLink(f.cover_youtube)!.id} alt="YouTube cover preview" className="h-full w-full" /></div> : f.cover_youtube ? <span className="text-xs text-destructive">Not a YouTube video link</span> : null}</div></F>}
    {f.cover_path && <div className="grid sm:grid-cols-2 gap-x-4"><F label="Photo caption (required)"><input className="field" value={f.cover_alt} onChange={(e) => set({ cover_alt: e.target.value })} /></F><F label="Photo credit"><input className="field" value={f.cover_credit} onChange={(e) => set({ cover_credit: e.target.value })} /></F></div>}
    <div className="grid sm:grid-cols-2 gap-x-4"><F label="Tags (commas)"><input className="field" value={f.tags} onChange={(e) => set({ tags: e.target.value })} /></F><F label="Region"><input className="field" value={f.region} onChange={(e) => set({ region: e.target.value })} /></F><F label="Web address"><input className="field" value={f.slug} onChange={(e) => set({ slug: slug(e.target.value) })} placeholder="auto from the English title" /></F>
      <F label="Status"><StatusSelect value={f.status} onChange={(v) => set({ status: v as typeof f.status })} canPublish={canPublish} /></F>{f.status === 'scheduled' && <F label="Publish time"><input type="datetime-local" className="field" value={f.publish_at} onChange={(e) => set({ publish_at: e.target.value })} /></F>}</div>
    <details className="mt-4"><summary className="cursor-pointer text-sm font-semibold">Search appearance (optional)</summary><F label="Search title"><input className="field" value={f.seo_title} onChange={(e) => set({ seo_title: e.target.value })} /></F><F label="Search description"><textarea className="field" value={f.seo_description} onChange={(e) => set({ seo_description: e.target.value })} /></F></details>
    <SourcesEditor items={sources} onChange={setSources} library={data.sources} /><div className="mt-6 flex gap-3"><Button disabled={busy} onClick={submit}><Save />Save post</Button><Button variant="outline" onClick={onDone}>Cancel</Button></div></div>;
}
function PostsAdmin(p: { categories: Category[]; canPublish: boolean; media: Media[]; userId: string }) {
  const { data } = useSuspenseQuery(hubOptions); const [edit, setEdit] = useState<PostRow | 'new' | null>(null); const { run } = useSaver();
  return <><div className="flex justify-between gap-3 mb-6"><h1 className="text-3xl font-bold">Blogs &amp; Posts</h1><Button onClick={() => setEdit('new')}><Plus />New post</Button></div>
    {edit && <PostForm key={edit === 'new' ? 'new' : edit.id} {...(edit === 'new' ? {} : { row: edit })} onDone={() => setEdit(null)} {...p} />}
    <div className="admin-panel overflow-x-auto">{data.posts.length ? <table className="w-full text-sm"><tbody>{data.posts.map((x) => <tr key={x.id} className="border-b border-border"><td className="py-3"><p className="font-semibold">{x.title_te || x.title_en || '(untitled)'}</p><p className="text-xs text-muted-foreground">{x.post_type.replace('_', ' ')} · {categoryName(p.categories.find((c) => c.id === x.category_id), 'en') || 'No category'}</p></td><td>{badge(x.status)}</td><td className="text-right whitespace-nowrap"><Button size="sm" variant="outline" onClick={() => setEdit(x)}>Edit</Button>{p.canPublish && <Button size="icon" variant="ghost" aria-label="Delete" onClick={() => { if (window.confirm('Delete this post permanently?')) void run({ kind: 'delete', value: { table: 'posts', id: x.id } }, 'Deleted'); }}><Trash2 /></Button>}</td></tr>)}</tbody></table> : <p className="text-sm text-muted-foreground">No posts yet.</p>}</div></>;
}

/* ------------------------------ Data Library ------------------------------ */
function DataForm({ row, onDone, canPublish }: { row?: DataCardRow; onDone: () => void; canPublish: boolean }) {
  const { data } = useSuspenseQuery(hubOptions); const { run, busy } = useSaver();
  const rows0 = (Array.isArray(row?.chart_data) ? row.chart_data : []) as { label: string; value: number }[];
  const [f, setF] = useState({ name_te: row?.name_te || '', name_en: row?.name_en || '', unit: row?.unit || '', geography: row?.geography || '', data_year: row?.data_year ? String(row.data_year) : '', comparison_year: row?.comparison_year ? String(row.comparison_year) : '', chart_type: (row?.chart_type || 'bar') as 'bar' | 'line' | 'table', rows: rows0.map((r) => `${r.label}, ${r.value}`).join('\n'), source_id: row?.source_id || '', verified_at: row?.verified_at || '', notes: row?.notes || '', status: (row?.status || 'draft') as 'draft' | 'published' | 'archived' });
  const set = (p: Partial<typeof f>) => setF((x) => ({ ...x, ...p })); const older = isOlderData(Number(f.data_year) || null);
  async function submit() {
    const chart = f.rows.split('\n').map((l) => l.trim()).filter(Boolean).map((l) => { const i = l.lastIndexOf(','); return { label: l.slice(0, i).trim(), value: Number(l.slice(i + 1)) }; });
    if (chart.some((c) => !c.label || Number.isNaN(c.value))) { toast.error('Each chart line must look like: Label, 123'); return; }
    const r = await run({ kind: 'data_card', value: { ...(row ? { id: row.id } : {}), name_te: f.name_te, name_en: f.name_en, unit: f.unit, geography: f.geography, data_year: f.data_year ? Number(f.data_year) : null, comparison_year: f.comparison_year ? Number(f.comparison_year) : null, chart_type: f.chart_type, chart_data: chart, source_id: f.source_id || null, verified_at: f.verified_at || null, notes: f.notes, status: f.status } }, 'Data card saved');
    if (r) onDone();
  }
  return <div className="admin-panel mb-8"><div className="flex justify-between"><h2 className="font-bold text-xl">{row ? 'Edit data card' : 'New data card'}</h2><Button variant="ghost" size="icon" aria-label="Close" onClick={onDone}><X /></Button></div>
    <div className="grid sm:grid-cols-2 gap-x-4"><F label="Name (Telugu)"><input className="field" value={f.name_te} onChange={(e) => set({ name_te: e.target.value })} /></F><F label="Name (English)"><input className="field" value={f.name_en} onChange={(e) => set({ name_en: e.target.value })} /></F>
      <F label="Geography"><input className="field" value={f.geography} onChange={(e) => set({ geography: e.target.value })} placeholder="India / Andhra Pradesh / Visakhapatnam…" /></F><F label="Unit"><input className="field" value={f.unit} onChange={(e) => set({ unit: e.target.value })} placeholder="% / ₹ lakh / persons" /></F>
      <F label="Data year (required to publish)"><input className="field" inputMode="numeric" value={f.data_year} onChange={(e) => set({ data_year: e.target.value })} /></F><F label="Baseline / comparison year (e.g. 2011)"><input className="field" inputMode="numeric" value={f.comparison_year} onChange={(e) => set({ comparison_year: e.target.value })} /></F>
      <F label="Source (required to publish)"><select className="field" value={f.source_id} onChange={(e) => set({ source_id: e.target.value })}><option value="">— choose from the Source Library —</option>{data.sources.map((s) => <option key={s.id} value={s.id}>{s.ref} · {s.name.slice(0, 70)}</option>)}</select></F><F label="Date verified (required to publish)"><input type="date" className="field" value={f.verified_at} onChange={(e) => set({ verified_at: e.target.value })} /></F>
      <F label="Chart type"><select className="field" value={f.chart_type} onChange={(e) => set({ chart_type: e.target.value as typeof f.chart_type })}><option value="bar">Bars</option><option value="line">Line</option><option value="table">Table</option></select></F><F label="Status"><select className="field" value={f.status} onChange={(e) => set({ status: e.target.value as typeof f.status })}><option value="draft">Draft</option>{canPublish && <><option value="published">Published</option><option value="archived">Archived</option></>}</select></F></div>
    {older && <p className="text-sm mt-3 text-accent-foreground bg-accent/20 rounded p-2">This data year is more than 3 years old. Visitors will see an “Older data” label. Add a newer figure if one exists.</p>}
    <F label="Chart numbers (one per line: Label, value)" hint="Example: 2011, 62.4  then  2024, 71.9"><textarea className="field min-h-28 font-mono" value={f.rows} onChange={(e) => set({ rows: e.target.value })} /></F>
    <F label="Internal notes (not public)"><textarea className="field" value={f.notes} onChange={(e) => set({ notes: e.target.value })} /></F>
    <div className="mt-6 flex gap-3"><Button disabled={busy} onClick={submit}><Save />Save data card</Button><Button variant="outline" onClick={onDone}>Cancel</Button></div></div>;
}
function DataAdmin({ canPublish }: { canPublish: boolean }) {
  const { data } = useSuspenseQuery(hubOptions); const [edit, setEdit] = useState<DataCardRow | 'new' | null>(null); const { run } = useSaver();
  return <><div className="flex justify-between gap-3 mb-6"><h1 className="text-3xl font-bold">Data Library</h1><Button onClick={() => setEdit('new')}><Plus />New data card</Button></div>
    {edit && <DataForm key={edit === 'new' ? 'new' : edit.id} {...(edit === 'new' ? {} : { row: edit })} onDone={() => setEdit(null)} canPublish={canPublish} />}
    <div className="admin-panel overflow-x-auto">{data.dataCards.length ? <table className="w-full text-sm"><tbody>{data.dataCards.map((c) => <tr key={c.id} className="border-b border-border"><td className="py-3"><p className="font-semibold">{c.name_te || c.name_en}</p><p className="text-xs text-muted-foreground">{c.geography} · data {c.data_year ?? '—'}{c.comparison_year ? ` vs ${c.comparison_year}` : ''}{isOlderData(c.data_year) ? ' · older data' : ''}</p></td><td>{badge(c.status)}</td><td className="text-right whitespace-nowrap"><Button size="sm" variant="outline" onClick={() => setEdit(c)}>Edit</Button>{canPublish && <Button size="icon" variant="ghost" aria-label="Delete" onClick={() => { if (window.confirm('Delete this data card?')) void run({ kind: 'delete', value: { table: 'data_cards', id: c.id } }, 'Deleted'); }}><Trash2 /></Button>}</td></tr>)}</tbody></table> : <p className="text-sm text-muted-foreground">No data cards yet. Every card needs a source, a data year and a verified date before it can be published.</p>}</div></>;
}

/* ------------------------------ Source Library ------------------------------ */
function SourcesAdmin({ canPublish }: { canPublish: boolean }) {
  const { data } = useSuspenseQuery(hubOptions); const { run, busy } = useSaver(); const [q, setQ] = useState(''); const [edit, setEdit] = useState<Partial<SourceRow> | null>(null);
  const uses = useMemo(() => { const m = new Map<string, number>(); data.contentSources.forEach((c) => c.source_id && m.set(c.source_id, (m.get(c.source_id) || 0) + 1)); data.dataCards.forEach((c) => c.source_id && m.set(c.source_id, (m.get(c.source_id) || 0) + 1)); return m; }, [data]);
  const list = data.sources.filter((s) => (s.name + s.organisation + s.category + s.website + s.ref).toLowerCase().includes(q.toLowerCase()));
  const set = (p: Partial<SourceRow>) => setEdit((x) => ({ ...x, ...p }));
  return <><div className="flex flex-wrap justify-between gap-3 mb-6"><h1 className="text-3xl font-bold">Source Library</h1><Button onClick={() => setEdit({ source_type: 'government' })}><Plus />Add source</Button></div>
    {edit && <div className="admin-panel mb-8"><div className="grid sm:grid-cols-2 gap-x-4"><F label="Name"><input className="field" value={edit.name || ''} onChange={(e) => set({ name: e.target.value })} /></F><F label="Organisation"><input className="field" value={edit.organisation || ''} onChange={(e) => set({ organisation: e.target.value })} /></F><F label="Website"><input className="field" value={edit.website || ''} onChange={(e) => set({ website: e.target.value })} /></F><F label="Category"><input className="field" value={edit.category || ''} onChange={(e) => set({ category: e.target.value })} /></F>
      <F label="Type"><select className="field" value={edit.source_type || 'government'} onChange={(e) => set({ source_type: e.target.value })}>{SOURCE_TYPES.map((t) => <option key={t} value={t}>{SOURCE_TYPE_LABELS[t]}</option>)}</select></F><F label="Freshness / reliability note"><input className="field" value={edit.reliability_note || ''} onChange={(e) => set({ reliability_note: e.target.value })} /></F></div><F label="What you get / usage tips"><textarea className="field" value={edit.usage_tips || ''} onChange={(e) => set({ usage_tips: e.target.value })} /></F>
      <div className="mt-5 flex gap-3"><Button disabled={busy} onClick={async () => { const r = await run({ kind: 'source', value: { ...(edit.id ? { id: edit.id } : {}), ref: edit.ref || '', name: edit.name || '', organisation: edit.organisation || '', website: edit.website || '', category: edit.category || '', source_type: (edit.source_type || 'government') as 'government', reliability_note: edit.reliability_note || '', usage_tips: edit.usage_tips || '' } }, 'Source saved'); if (r) setEdit(null); }}><Save />Save</Button><Button variant="outline" onClick={() => setEdit(null)}>Cancel</Button></div></div>}
    <input className="field mb-4 max-w-md" placeholder="Search sources…" value={q} onChange={(e) => setQ(e.target.value)} aria-label="Search sources" />
    <div className="admin-panel overflow-x-auto"><table className="w-full text-sm"><tbody>{list.map((s) => <tr key={s.id} className="border-b border-border align-top"><td className="py-3 pr-3 text-xs text-muted-foreground">{s.ref}</td><td className="py-3"><p className="font-semibold">{s.name}</p><p className="text-xs text-muted-foreground">{s.category} · {SOURCE_TYPE_LABELS[s.source_type as keyof typeof SOURCE_TYPE_LABELS] || s.source_type}</p>{s.usage_tips && <p className="text-xs mt-1">{s.usage_tips}</p>}{s.reliability_note && <p className="text-xs text-muted-foreground mt-1">Note: {s.reliability_note}</p>}</td><td className="text-xs whitespace-nowrap">{s.website && <a className="text-primary inline-flex gap-1 items-center" target="_blank" rel="noopener noreferrer" href={/^https?:\/\//i.test(s.website) ? s.website : `https://${s.website.split(/[\s/]+/)[0]}`}><ExternalLink size={12} />Open</a>}<p className="text-muted-foreground mt-1">Used in {uses.get(s.id) || 0}</p></td><td className="text-right whitespace-nowrap"><Button size="sm" variant="outline" onClick={() => setEdit(s)}>Edit</Button>{canPublish && <Button size="icon" variant="ghost" aria-label="Delete" onClick={() => { if (window.confirm('Delete this source?')) void run({ kind: 'delete', value: { table: 'sources', id: s.id } }, 'Deleted'); }}><Trash2 /></Button>}</td></tr>)}</tbody></table></div></>;
}

/* ------------------------------ Content Planner ------------------------------ */
const CHECKS = ['Data collected', 'Sources verified', 'Right of reply sent', 'Script reviewed', 'Thumbnail ready'];
const planPayload = (r: PlannerRow, over: Partial<PlannerRow> = {}) => { const x = { ...r, ...over }; return { id: x.id, title_te: x.title_te, title_en: x.title_en, category_id: x.category_id, region: x.region, stage: x.stage as (typeof PLANNER_STAGES)[number], planned_date: x.planned_date, due_date: x.due_date, owner: x.owner, core_question: x.core_question, data_to_collect: x.data_to_collect, suggested_sources: x.suggested_sources, viewer_ask: x.viewer_ask, script_html: x.script_html, checklist: (x.checklist && typeof x.checklist === 'object' ? x.checklist : {}) as Record<string, boolean>, query_id: x.query_id, video_id: x.video_id, post_id: x.post_id, sort_order: x.sort_order }; };
function PlannerItem({ item, onClose, team, categories }: { item: PlannerRow; onClose: () => void; team: Team; categories: Category[] }) {
  const { data } = useSuspenseQuery(hubOptions); const { run, busy } = useSaver(); const qc = useQueryClient(); const cget = useServerFn(getPlannerComments);
  const [f, setF] = useState(planPayload(item)); const [comment, setComment] = useState(''); const [comments, setComments] = useState<{ id: string; body: string; author: string | null; created_at: string }[] | null>(null);
  const set = (p: Partial<typeof f>) => setF((x) => ({ ...x, ...p })); const checks = f.checklist;
  const load = async () => setComments(await cget({ data: { id: item.id } }).catch(() => []));
  if (comments === null) void load();
  const tasks = data.tasks.filter((t) => t.planner_item_id === item.id);
  async function makeVideo() { const r = await run({ kind: 'video', value: { slug: slug(f.title_en) || '', title_te: f.title_te, title_en: f.title_en, description_te: '', description_en: '', youtube: '', category_id: f.category_id, tags: [], region: f.region, language: 'te', series: '', status: 'draft', is_featured: false, show_in_ticker: true, social_links: { youtube: '', instagram: '', facebook: '' }, seo_title: '', seo_description: '' } }, 'Video draft created'); if (r) await run({ kind: 'planner', value: { ...f, video_id: r.id } }, 'Linked'); }
  return <div className="admin-panel mb-8 border-primary"><div className="flex justify-between"><h2 className="font-bold text-xl">Planner card</h2><Button variant="ghost" size="icon" aria-label="Close" onClick={onClose}><X /></Button></div>
    <div className="grid sm:grid-cols-2 gap-x-4"><F label="Title (Telugu)"><input className="field" value={f.title_te} onChange={(e) => set({ title_te: e.target.value })} /></F><F label="Title (English)"><input className="field" value={f.title_en} onChange={(e) => set({ title_en: e.target.value })} /></F>
      <F label="Category"><CatSelect value={f.category_id} onChange={(v) => set({ category_id: v })} categories={categories} /></F><F label="Stage"><select className="field" value={f.stage} onChange={(e) => set({ stage: e.target.value as typeof f.stage })}>{PLANNER_STAGES.map((s) => <option key={s} value={s}>{STAGE_LABELS[s]}</option>)}</select></F>
      <F label="Planned publish date"><input type="date" className="field" value={f.planned_date || ''} onChange={(e) => set({ planned_date: e.target.value || null })} /></F><F label="Due date (research / script)"><input type="date" className="field" value={f.due_date || ''} onChange={(e) => set({ due_date: e.target.value || null })} /></F>
      <F label="Owner"><select className="field" value={f.owner || ''} onChange={(e) => set({ owner: e.target.value || null })}><option value="">Unassigned</option>{team.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}</select></F><F label="Region"><input className="field" value={f.region} onChange={(e) => set({ region: e.target.value })} /></F></div>
    <F label="Core question to put to the government"><textarea className="field" value={f.core_question} onChange={(e) => set({ core_question: e.target.value })} /></F><F label="Data to collect (2011 baseline → latest year)"><textarea className="field" value={f.data_to_collect} onChange={(e) => set({ data_to_collect: e.target.value })} /></F><F label="Suggested sources"><textarea className="field" value={f.suggested_sources} onChange={(e) => set({ suggested_sources: e.target.value })} /></F><F label="Ask viewers to send"><input className="field" value={f.viewer_ask} onChange={(e) => set({ viewer_ask: e.target.value })} /></F>
    <div className="mt-4"><label className="field-label">Checklist</label><div className="flex flex-wrap gap-x-6 gap-y-2">{CHECKS.map((c) => <label key={c} className="text-sm flex gap-2 items-center"><input type="checkbox" checked={!!checks[c]} onChange={(e) => set({ checklist: { ...checks, [c]: e.target.checked } })} />{c}</label>)}</div></div>
    <F label="Script (use the standard 9-part structure)"><StoryEditor key={item.id} value={f.script_html || '<p></p>'} onChange={(v) => set({ script_html: v })} /></F>
    <div className="mt-6 flex flex-wrap gap-3"><Button disabled={busy} onClick={async () => { const r = await run({ kind: 'planner', value: f }, 'Planner card saved'); if (r) onClose(); }}><Save />Save card</Button>{!f.video_id && <Button variant="outline" disabled={busy} onClick={makeVideo}><Youtube />Create video draft</Button>}{f.query_id && <span className="text-xs self-center text-muted-foreground">Linked to a citizen issue — publishing this card updates the issue to “Published”.</span>}</div>
    <div className="mt-8 grid md:grid-cols-2 gap-6"><div><h3 className="font-bold">Comments</h3>{(comments || []).map((c) => <div key={c.id} className="border-b border-border py-2 text-sm"><p>{c.body}</p><p className="text-[11px] text-muted-foreground">{team.find((m) => m.id === c.author)?.name || 'Team'} · {new Date(c.created_at).toLocaleString()}</p></div>)}<div className="flex gap-2 mt-3"><input className="field" value={comment} onChange={(e) => setComment(e.target.value)} placeholder="Add a comment" aria-label="Comment" /><Button disabled={!comment.trim() || busy} onClick={async () => { await run({ kind: 'comment', value: { item_id: item.id, body: comment } }, 'Comment added'); setComment(''); setComments(null); }}>Add</Button></div></div>
      <div><h3 className="font-bold">Tasks</h3>{tasks.map((t) => <div key={t.id} className="flex gap-2 items-center py-1 text-sm"><select className="field !w-auto" value={t.status} onChange={(e) => void run({ kind: 'task', value: { id: t.id, title: t.title, assignee: t.assignee, due_date: t.due_date, planner_item_id: t.planner_item_id, status: e.target.value as 'open' } }, 'Task updated')}>{['open', 'in_progress', 'blocked', 'done'].map((s) => <option key={s} value={s}>{s.replace('_', ' ')}</option>)}</select><span>{t.title}</span></div>)}<TaskAdd itemId={item.id} team={team} /></div></div>
    <button className="hidden" onClick={() => qc.invalidateQueries()} aria-hidden="true" /></div>;
}
function TaskAdd({ itemId, team }: { itemId: string | null; team: Team }) {
  const { run, busy } = useSaver(); const [t, setT] = useState(''); const [a, setA] = useState(''); const [d, setD] = useState('');
  return <div className="flex flex-wrap gap-2 mt-3"><input className="field !w-auto flex-1 min-w-40" placeholder="New task" value={t} onChange={(e) => setT(e.target.value)} aria-label="New task" /><select className="field !w-auto" value={a} onChange={(e) => setA(e.target.value)} aria-label="Assign to"><option value="">Unassigned</option>{team.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}</select><input type="date" className="field !w-auto" value={d} onChange={(e) => setD(e.target.value)} aria-label="Due date" /><Button disabled={busy || t.trim().length < 2} onClick={async () => { await run({ kind: 'task', value: { title: t, assignee: a || null, due_date: d || null, planner_item_id: itemId, status: 'open' } }, 'Task added'); setT(''); }}><Plus />Add</Button></div>;
}
function PlannerAdmin({ team, categories, focusId = null, onFocusUsed }: { team: Team; categories: Category[]; focusId?: string | null; onFocusUsed?: () => void }) {
  const { data } = useSuspenseQuery(hubOptions); const { run } = useSaver(); const [view, setView] = useState<'board' | 'calendar' | 'tasks'>('board'); const [open, setOpen] = useState<PlannerRow | null>(() => (focusId ? data.planner.find((i) => i.id === focusId) || null : null));
  const [mine, setMine] = useState('');
  useEffect(() => { if (focusId) { const it = data.planner.find((i) => i.id === focusId); if (it) setOpen(it); onFocusUsed?.(); } }, [focusId]); // eslint-disable-line react-hooks/exhaustive-deps
  const items = data.planner.filter((i) => !mine || i.owner === mine); const cat = (id: string | null) => categoryName(categories.find((c) => c.id === id), 'en') || '';
  const move = (i: PlannerRow, stage: string) => void run({ kind: 'planner', value: planPayload(i, { stage }) }, 'Moved');
  const byWeek = useMemo(() => { const m = new Map<string, PlannerRow[]>(); items.filter((i) => i.planned_date).forEach((i) => { const d = new Date(i.planned_date + 'T00:00:00'); const mon = new Date(d); mon.setDate(d.getDate() - ((d.getDay() + 6) % 7)); const k = mon.toISOString().slice(0, 10); m.set(k, [...(m.get(k) || []), i]); }); return [...m.entries()].sort(); }, [items]);
  return <><div className="flex flex-wrap justify-between gap-3 mb-6"><h1 className="text-3xl font-bold">Content Planner</h1><div className="flex flex-wrap gap-3"><select className="field !w-auto" value={mine} onChange={(e) => setMine(e.target.value)} aria-label="Filter by owner"><option value="">Everyone</option>{team.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}</select>{(['board', 'calendar', 'tasks'] as const).map((v) => <Button key={v} size="sm" variant={view === v ? 'default' : 'outline'} onClick={() => setView(v)}>{v === 'board' ? 'Board' : v === 'calendar' ? 'Calendar' : 'Tasks'}</Button>)}<Button size="sm" onClick={async () => { const r = await run({ kind: 'planner', value: { title_te: '', title_en: 'New topic', category_id: null, region: '', stage: 'idea', planned_date: null, due_date: null, owner: null, core_question: '', data_to_collect: '', suggested_sources: '', viewer_ask: '', script_html: '', checklist: {}, query_id: null, video_id: null, post_id: null, sort_order: 0 } }, 'Card created'); if (r) setOpen(null); }}><Plus />New card</Button></div></div>
    {open && <PlannerItem key={open.id} item={open} onClose={() => setOpen(null)} team={team} categories={categories} />}
    {view === 'board' && <div className="overflow-x-auto pb-4"><div className="flex gap-4 min-w-max">{PLANNER_STAGES.map((s) => { const col = items.filter((i) => i.stage === s); return <div key={s} className="w-64 shrink-0"><h3 className="text-xs font-bold uppercase mb-2">{STAGE_LABELS[s]} <span className="text-muted-foreground">({col.length})</span></h3><div className="space-y-3">{col.map((i) => <div key={i.id} className="bg-card border border-border rounded-lg p-3 text-sm"><button className="text-left font-semibold hover:text-primary" onClick={() => setOpen(i)}>{i.title_te || i.title_en || '(untitled)'}</button><p className="text-[11px] text-muted-foreground mt-1">{cat(i.category_id)}{i.planned_date ? ` · ${i.planned_date}` : ''}</p>{i.owner && <p className="text-[11px]">👤 {team.find((m) => m.id === i.owner)?.name}</p>}<select className="field !h-8 !text-xs mt-2" value={i.stage} aria-label="Move to stage" onChange={(e) => move(i, e.target.value)}>{PLANNER_STAGES.map((x) => <option key={x} value={x}>{STAGE_LABELS[x]}</option>)}</select></div>)}</div></div>; })}</div></div>}
    {view === 'calendar' && <div className="space-y-6">{byWeek.map(([wk, list]) => <div key={wk} className="admin-panel"><h3 className="font-bold flex gap-2 items-center"><CalendarDays size={16} />Week of {new Date(wk + 'T00:00:00').toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' })}</h3>{list.sort((a, b) => (a.planned_date || '').localeCompare(b.planned_date || '')).map((i) => <button key={i.id} onClick={() => setOpen(i)} className="w-full text-left flex gap-4 py-2 border-b border-border text-sm hover:bg-muted/50"><span className="w-28 shrink-0 text-muted-foreground">{new Date(i.planned_date + 'T00:00:00').toLocaleDateString(undefined, { weekday: 'short', day: 'numeric', month: 'short' })}</span><span className="flex-1 font-medium">{i.title_te || i.title_en}</span><span className="text-xs text-muted-foreground">{cat(i.category_id)}</span>{badge(i.stage === 'published' ? 'published' : i.stage)}</button>)}</div>)}{!byWeek.length && <p className="text-sm text-muted-foreground">No dated cards.</p>}</div>}
    {view === 'tasks' && <div className="admin-panel"><TaskAdd itemId={null} team={team} />{data.tasks.map((t) => <div key={t.id} className="flex flex-wrap gap-3 items-center py-2 border-b border-border text-sm"><select className="field !w-auto" value={t.status} onChange={(e) => void run({ kind: 'task', value: { id: t.id, title: t.title, assignee: t.assignee, due_date: t.due_date, planner_item_id: t.planner_item_id, status: e.target.value as 'open' } }, 'Task updated')}>{['open', 'in_progress', 'blocked', 'done'].map((s) => <option key={s} value={s}>{s.replace('_', ' ')}</option>)}</select><span className="flex-1">{t.title}</span><span className="text-xs text-muted-foreground">{team.find((m) => m.id === t.assignee)?.name || 'Unassigned'}{t.due_date ? ` · due ${t.due_date}` : ''}</span></div>)}{!data.tasks.length && <p className="text-sm text-muted-foreground mt-3">No tasks yet.</p>}</div>}</>;
}

/* ------------------------------ Activity Log ------------------------------ */
function ActivityAdmin({ team }: { team: Team }) {
  const { data } = useSuspenseQuery(hubOptions); const name = (id: string | null) => (id ? team.find((m) => m.id === id)?.name || id.slice(0, 8) : 'System');
  return <><h1 className="text-3xl font-bold mb-6">Activity Log</h1><div className="admin-panel overflow-x-auto"><table className="w-full text-sm"><thead><tr className="text-left text-xs uppercase text-muted-foreground"><th className="py-2">When</th><th>Who</th><th>What</th><th>Item</th></tr></thead><tbody>{data.audit.map((a) => { const d = (a.detail && typeof a.detail === 'object' ? a.detail : {}) as Record<string, string>; return <tr key={a.id} className="border-b border-border"><td className="py-2 whitespace-nowrap">{new Date(a.created_at).toLocaleString()}</td><td>{name(a.actor)}</td><td>{a.action} · {a.entity.replace('_', ' ')}{d['status'] ? ` → ${d['status']}` : ''}{d['role'] ? ` → ${d['role']}` : ''}</td><td className="max-w-xs truncate">{d['title'] || ''}</td></tr>; })}</tbody></table>{!data.audit.length && <p className="text-sm text-muted-foreground py-3">Nothing recorded yet.</p>}</div></>;
}

export function HubAdmin({ kind, team, categories, media, userId, canPublish, focusId = null, onFocusUsed }: { kind: HubKind; team: Team; categories: Category[]; media: Media[]; userId: string; canPublish: boolean; focusId?: string | null; onFocusUsed?: () => void }) {
  if (kind === 'videos') return <VideosAdmin categories={categories} canPublish={canPublish} />;
  if (kind === 'posts') return <PostsAdmin categories={categories} canPublish={canPublish} media={media} userId={userId} />;
  if (kind === 'data') return <DataAdmin canPublish={canPublish} />;
  if (kind === 'sources') return <SourcesAdmin canPublish={canPublish} />;
  if (kind === 'planner') return <PlannerAdmin team={team} categories={categories} focusId={focusId} {...(onFocusUsed ? { onFocusUsed } : {})} />;
  return <ActivityAdmin team={team} />;
}
